window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-39601\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταπείνωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 143 na letra τ · nº geral 39601</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Astron. abaixamento; inclinação de um astro. 〈ταπεινόω〉</p></section></article>\n<article id=\"entry-dgp-39602\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταπεινῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 144 na letra τ · nº geral 39602</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 humildemente 2 rasteiramente; vulgarmente, em rel. a estilo 3 crist. de modo banal; trivialmente.</p></section></article>\n<article id=\"entry-dgp-39603\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταπείνωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 145 na letra τ · nº geral 39603</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rebaixamento; diminuição; humilhação 2 desencorajamento 3 abatimento; prostração 4 baixeza; vulgaridade de estilo 5 Astron. inclinação. 〈ταπεινόω〉</p></section></article>\n<article id=\"entry-dgp-39604\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάπης, ητος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 146 na letra τ · nº geral 39604</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tapete; cobertura.</p></section></article>\n<article id=\"entry-dgp-39605\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἀπί</h1><div class=\"entry-meta\"><span>DGP · ordem 147 na letra τ · nº geral 39605</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τὰ ἐπί.</p></section></article>\n<article id=\"entry-dgp-39606\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἀπίλοιπα</h1><div class=\"entry-meta\"><span>DGP · ordem 148 na letra τ · nº geral 39606</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase poét. de τὰ ἐπίλοιπα.</p></section></article>\n<article id=\"entry-dgp-39607\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάπις, ιδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 149 na letra τ · nº geral 39607</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">τάπης.</p></section></article>\n<article id=\"entry-dgp-39608\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἀπό</h1><div class=\"entry-meta\"><span>DGP · ordem 150 na letra τ · nº geral 39608</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τὸ ἀπό.</p></section></article>\n<article id=\"entry-dgp-39609\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἄπορον</h1><div class=\"entry-meta\"><span>DGP · ordem 151 na letra τ · nº geral 39609</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase poét. de τὸ ἄπορον.</p></section></article>\n<article id=\"entry-dgp-39610\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἀπόρρητα</h1><div class=\"entry-meta\"><span>DGP · ordem 152 na letra τ · nº geral 39610</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τὰ ἀπόρρητα.</p></section></article>\n<article id=\"entry-dgp-39611\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἄρ</h1><div class=\"entry-meta\"><span>DGP · ordem 153 na letra τ · nº geral 39611</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de τοι ἄρ.</p></section></article>\n<article id=\"entry-dgp-39612\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἄρα</h1><div class=\"entry-meta\"><span>DGP · ordem 154 na letra τ · nº geral 39612</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e τἆρα crase át. de τοι ἄρα.</p></section></article>\n<article id=\"entry-dgp-39613\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταραγμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 155 na letra τ · nº geral 39613</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perturbação; agitação; confusão. 〈τα­ράσσω〉</p></section></article>\n<article id=\"entry-dgp-39614\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταρακτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 156 na letra τ · nº geral 39614</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">próprio para perturbar; perturbador; agitador, gen. 〈ταράσσω〉</p></section></article>\n<article id=\"entry-dgp-39615\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάρανδος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 157 na letra τ · nº geral 39615</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rena, animal.</p></section></article>\n<article id=\"entry-dgp-39616\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταραντῖνος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 158 na letra τ · nº geral 39616</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Tarento; tarentino. 〈Τάρας〉</p></section></article>\n<article id=\"entry-dgp-39617\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάραξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 159 na letra τ · nº geral 39617</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 agitação; perturbação; confusão 2 Medic. distúrbio intestinal 3 Medic. inflamação dos olhos. 〈ταράσσω〉</p></section></article>\n<article id=\"entry-dgp-39618\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τάρας, αντος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 160 na letra τ · nº geral 39618</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tarento, cidade da Magna Grécia.</p></section></article>\n<article id=\"entry-dgp-39619\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταράσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 161 na letra τ · nº geral 39619</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω (fut. ταράξω, aor. ἐτάραξα, perf. ép. intr. τέτρηχα; pas. fut. ταράξομαι, aor. ἐταράχθην, perf. τετάραγμαι, m.-q.-perf. ἐτεταράγμην) 1 agitar fisicamente; remexer; revolver: τ. φάρμακον luc. preparar um medicamento agitando os ingredientes, τ. πόντον hom. agitar o mar, levantar as ondas 2 semear desordem em; desorganizar; tumultuar (um exército) 3 Medic. provocar distúrbios; desarranjar (o ventre) 4 excitar; suscitar; provocar algo (querela, acusação), contra alguém, dat. 5 agitar espiritualmente; pôr em estado de agitação interior; perturbar; atormentar; inquietar: ὅταν ταράξῃ Κύπρις ἡβῶσαν φρένα eur. quando Cípris perturba o coração juvenil, ἵππους ἐτάραξε hom. assustou os cavalos 6 perf. intr. estar agitado; estar perturbado: τετρήκει δ᾽ ἀγορή hom. a assembléia estava tumultuada ♦ pas. 7 agitar-se: θάλασσα ταράσσεται plut. o mar começa a agitar-se, está revolto, πόντος ταραχθείς eur. mar revolto, mar em fúria 8 estar em estado de perturbação; alterar-se: οἱ ἱππικοὶ διὰ τὸ μὴ ταράττεσθαι ἐπὶ τῶν ἵππων δύνανται ἅμα ἱππεύον­τες καὶ ὁρᾶν καὶ ἀκούειν καὶ λέγειν τὸ δέον xen. os cavaleiros, pelo fato de não se perturbarem montados nos cavalos, podem, enquanto cavalgam, tanto ver como ouvir e falar o que é preciso 9 cair na desordem ou confusão: ἐν σφίσιν αὐτοῖς ταρασσόμενοι tuc. confundidos uns com os outros, πράγματα τεταραγμένα dem. negócios confusos, desordenados 10 sofrer perturbação em rel. a, ac.: ταράσσεσθαι φρένας sóf. ter o espírito perturbado 11 assustar-se; ser tomado de pavor 12 Medic. sofrer distúrbio: ταράττομαι τὴν γαστέρα ar. tenho desarranjo na barriga 13 ser posto em agitação ou confusão 14 ser suscitado: πόλεμος ἐταράχθην dem. a guerra foi provocada.</p></section></article>\n<article id=\"entry-dgp-39620\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταραχή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 162 na letra τ · nº geral 39620</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 perturbação; desordem; confusão: ταραχὴν ποιεῖν tuc. causar agitação, ἐς ταραχὴν καθιστάναι tuc. lançar na agitação, ἐν ταραχῇ καθεστηκέναι isócr. ter sido lançado em agitação, estar agitado 2 pl. motim; tumulto: ἐν ταραχαῖς εἶναι isócr. estar no tumulto, na agitação 3 revolta política; agitação; rebelião: ταραχὴν ταρέχειν plat. causar agitação 4 perturbação do espírito 5 Medic. distúrbio.</p></section></article>\n<article id=\"entry-dgp-39621\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταραχοποιός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 163 na letra τ · nº geral 39621</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que causa agitação; agitador. 〈ταραχή, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-39622\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάραχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 164 na letra τ · nº geral 39622</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ταραχή.</p></section></article>\n<article id=\"entry-dgp-39623\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταραχώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 165 na letra τ · nº geral 39623</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 perturbado; agitado 2 desordenado; confuso; tumultuado 3 Medic. perturbado por delírio; delirante 4 que agita; agitador; turbulento (pessoa) 5 perturbador; inquietante 6 desconcertante; perturbador; transtornante. 〈ταραχή〉</p></section></article>\n<article id=\"entry-dgp-39624\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταραχωδῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 166 na letra τ · nº geral 39624</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. confusamente.</p></section></article>\n<article id=\"entry-dgp-39625\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταρβαλέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 167 na letra τ · nº geral 39625</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 temeroso; medroso 2 assustado; apavorado 3 terrível; espantoso. 〈τάρβος〉</p></section></article>\n<article id=\"entry-dgp-39626\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταρβέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 168 na letra τ · nº geral 39626</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estar assustado; assustar-se; apavorar-se com algo, ac. 2 ter medo; temer algo, ac. ou inf. ou part. ou or. com μή: ταρβῶ μὲν εἰπεῖν τοὺς λόγους ἐλευθέ­ρους πρὸς τὸν τύραννον eur. receio dizer as palavras francas ao rei, i.e., receio usar de franqueza, ταρβῶν γε μή μοι Φοῖβος ἐξέλθῃ σαφής sóf. temeroso de que Febo se me manifeste nítido 3 partic. experimentar temor religioso; respeitar; venerar.</p></section></article>\n<article id=\"entry-dgp-39627\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάρβος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 169 na letra τ · nº geral 39627</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espanto; temor 2 motivo de temor 3 respeito religioso 4 pudor; timidez; acanhamento.</p></section></article>\n<article id=\"entry-dgp-39628\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταρβοσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 170 na letra τ · nº geral 39628</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">τάρβος.</p></section></article>\n<article id=\"entry-dgp-39629\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἆργα</h1><div class=\"entry-meta\"><span>DGP · ordem 171 na letra τ · nº geral 39629</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ou τἄργα crase át. de τὰ ἔργα.</p></section></article>\n<article id=\"entry-dgp-39630\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἀργύριον,</h1><div class=\"entry-meta\"><span>DGP · ordem 172 na letra τ · nº geral 39630</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. τἀργυρίου crase át. de τὸ ἀργύριον, τοῦ ἀργυρίου.</p></section></article>\n<article id=\"entry-dgp-39631\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταριχεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 173 na letra τ · nº geral 39631</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conservação em salmoura; salga 2 embalsamamento. 〈ταριχεύω〉</p></section></article>\n<article id=\"entry-dgp-39632\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταρίχευσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 174 na letra τ · nº geral 39632</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ταριχεία.</p></section></article>\n<article id=\"entry-dgp-39633\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταριχευτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 175 na letra τ · nº geral 39633</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">conservado em salmoura; salgado. 〈ταριχεύω〉</p></section></article>\n<article id=\"entry-dgp-39634\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταριχευτής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 176 na letra τ · nº geral 39634</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 salgador 2 embalsamador; mumificador. 〈ταριχεύω〉</p></section></article>\n<article id=\"entry-dgp-39635\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταριχεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 177 na letra τ · nº geral 39635</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conservar em salmoura; salgar (carne); fazer conservas 2 embalsamar; mumificar 3 (dor, velhice) consumir 4 aniquilar; acabrunhar. 〈τάριχος〉</p></section></article>\n<article id=\"entry-dgp-39636\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταριχηΐη</h1><div class=\"entry-meta\"><span>DGP · ordem 178 na letra τ · nº geral 39636</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ταριχεία.</p></section></article>\n<article id=\"entry-dgp-39637\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταριχοπωλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 179 na letra τ · nº geral 39637</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vender produtos em conserva. 〈ταριχοπώλης〉</p></section></article>\n<article id=\"entry-dgp-39638\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταριχοπώλης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 180 na letra τ · nº geral 39638</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comerciante de conservas. 〈τάριχος, πωλέω〉</p></section></article>\n<article id=\"entry-dgp-39639\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάριχος1, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 181 na letra τ · nº geral 39639</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">τάριχος2.</p></section></article>\n<article id=\"entry-dgp-39640\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάριχος2, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 182 na letra τ · nº geral 39640</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conserva; carne ou peixe salgados ou defumados 2 corpo embalsamado; múmia.</p></section></article>\n<article id=\"entry-dgp-39641\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάριχος3, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 183 na letra τ · nº geral 39641</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ταριχευτός.</p></section></article>\n<article id=\"entry-dgp-39642\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταρπήμεναι</h1><div class=\"entry-meta\"><span>DGP · ordem 184 na letra τ · nº geral 39642</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ταρπῆναι inf. aor.2 pas. ép. de τέρπω.</p></section></article>\n<article id=\"entry-dgp-39643\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τάρπιος λόφος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 185 na letra τ · nº geral 39643</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rocha Tarpeia, colina de Roma.</p></section></article>\n<article id=\"entry-dgp-39644\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταρρός, ταρρόω</h1><div class=\"entry-meta\"><span>DGP · ordem 186 na letra τ · nº geral 39644</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ταρσός, ταρσόω.</p></section></article>\n<article id=\"entry-dgp-39645\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταρσά, ῶν (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 187 na letra τ · nº geral 39645</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ταρσός.</p></section></article>\n<article id=\"entry-dgp-39646\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταρσεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 188 na letra τ · nº geral 39646</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">habitante de Tarso. 〈Ταρσός〉</p></section></article>\n<article id=\"entry-dgp-39647\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταρσόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 189 na letra τ · nº geral 39647</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. vindo de Tarso 〈Ταρσός, -θεν〉</p></section></article>\n<article id=\"entry-dgp-39648\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταρσοί, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 190 na letra τ · nº geral 39648</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Ταρσός.</p></section></article>\n<article id=\"entry-dgp-39649\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταρσός,</h1><div class=\"entry-meta\"><span>DGP · ordem 191 na letra τ · nº geral 39649</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ταρρός, οῦ pl. οἱ ταρσοί ou τὰ τάρσα (ὁ) 1 grade de caniço para curar queijos 2 rede, malha de caniços 3 entrelaçamento de raízes 3 planta do pé 4 palma da mão 5 dedo 6 orla da pálpebra 7 penas grossas sob as asas das aves 8 asa 9 pala do remo 10 fileira de remos 11 pl. remos.</p></section></article>\n<article id=\"entry-dgp-39650\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταρσός, οῦ (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 192 na letra τ · nº geral 39650</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tarso, capital da Cilícia.</p></section></article>\n<article id=\"entry-dgp-39651\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τάρσαρα</h1><div class=\"entry-meta\"><span>DGP · ordem 193 na letra τ · nº geral 39651</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. Τάρταρος.</p></section></article>\n<article id=\"entry-dgp-39652\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταρτάρειος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 194 na letra τ · nº geral 39652</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">do Tártaro. 〈Τάρταρος〉</p></section></article>\n<article id=\"entry-dgp-39653\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταρταρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 195 na letra τ · nº geral 39653</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tremer de frio; tiritar. 〈Τάρταρος〉</p></section></article>\n<article id=\"entry-dgp-39654\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τάρταρος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 196 na letra τ · nº geral 39654</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. τὰ Τάρταρα (ὁ) 1 Tártaro, morada subterrânea no fundo dos Infernos 2 infernos.</p></section></article>\n<article id=\"entry-dgp-39655\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταρταρόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 197 na letra τ · nº geral 39655</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crist. lançar no Tártaro, i.e., nos infernos. 〈Τάρταρος〉</p></section></article>\n<article id=\"entry-dgp-39656\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταρφέες, ταρφειαί</h1><div class=\"entry-meta\"><span>DGP · ordem 198 na letra τ · nº geral 39656</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ταρφύς.</p></section></article>\n<article id=\"entry-dgp-39657\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάρφθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 199 na letra τ · nº geral 39657</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. aor. pas. ép., τάρφθην aor. pas. ép., de τέρπω.</p></section></article>\n<article id=\"entry-dgp-39658\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάρφος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 200 na letra τ · nº geral 39658</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espessura; profundeza 2 matagal. 〈τρέφω〉</p></section></article>\n<article id=\"entry-dgp-39659\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταρφύς, ύς</h1><div class=\"entry-meta\"><span>DGP · ordem 201 na letra τ · nº geral 39659</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e εῖα, ύ 1 espesso; denso ♦ ταρφέα adv. 2 frequentemente.</p></section></article>\n<article id=\"entry-dgp-39660\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἀρχαῖα</h1><div class=\"entry-meta\"><span>DGP · ordem 202 na letra τ · nº geral 39660</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τὰ ἀρχαῖα.</p></section></article>\n<article id=\"entry-dgp-39661\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταρχύω</h1><div class=\"entry-meta\"><span>DGP · ordem 203 na letra τ · nº geral 39661</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut.ταρχύσω, aor. ἐτάρχυσα, perf. desus.; pas. aor. ἐταρχύθην, perf. τετάρχυμαι) at. e méd. prestar as honras fúnebres a alguém, ac.: ἔνθα ἑ ταρχύσουσι τύμβῳ τε στήλῃ τε hom. lá irão prestar-lhe as honras fúnebres com um túmulo e uma estela.</p></section></article>\n<article id=\"entry-dgp-39662\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 204 na letra τ · nº geral 39662</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tensão (de membro, de músculo) 2 contração ou franzimento (das sobrancelhas) 3 Ret. modulação (da voz) 4 tom: βαρεῖαι τάσεις καὶ ὀξεῖαι d.h. tons graves e agudos. 〈τείνω〉</p></section></article>\n<article id=\"entry-dgp-39663\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 205 na letra τ · nº geral 39663</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">neo-át. τάττω (fut. τάξω, aor. ἔταξα, perf. τέταχα; pas. fut. ταχθήσομαι, aor. ἐτάχθην, aor.2 ἐτάγην, perf. τέταγμαι, m.-q.-perf. ἐτετάγμην, fut. ant. τετάξομαι) ativa 1 pôr em certo arranjo; arranjar; dispor; acomodar; instalar algo ou alguém, ac. 2 Mil. alinhar; enfileirar; posicionar 3 incluir algo ou alguém, ac., em (uma classe), εἰς e ac. de n. abstrato, ἐν e dat., no domínio de, no âmbito de, κατά ou περί e ac.; enquadrar; classificar 4 dispor uma pessoa, ac., diante de outra (opositora ou subordinada), ἐπί e ac. 5 alinhar-se com alguém; tomar o partido de 6 designar; encarregar alguém, ac., de (uma tarefa), ἐπί e ac., dat. ou gen., ou para fazer algo, inf. 7 ordenar; fixar; determinar; ordenar ou mandar que, inf. 8 Gram. empregar uma palavra, ac., com o sentido de (outra), ἐπί e gen. média (aor. inf. τάξασθαι) 9 intr. colocar-se em seu posto; posicionar-se 10 arranjar, dispor algo, ac., para si ou em si 11 consentir em algo, ac.; comprometer-se a, inf. 12 fixar por si mesmo, segundo seu alvitre passiva 13 ser colocado; ser designado para um lugar; aor. e perf. estar postado; manter-se; achar-se em um lugar, εἰς e ac., ou gen. 14 manter-se alinhado em favor de alguém, σύν e dat., πρός e ac.; pertencer ao exército de, σύν e dat. 15 ser colocado em seu lugar; ser posto em ordem; ser determinado; ser prescrito; ser imposto 16 submeter-se às ordens de alguém, ὑπό e gen. 17 ser encarregado de, ἐπί e ac. ou dat., πρός e ac.; receber ordens para fazer algo, inf. 18 receber a imposição de, inf. 19 ser incluído em uma classe, ac.; ser enquadrado; ser classificado 1 τίνα μέσον τάξω λόγον; eur. que parte de minha fala devo pôr no centro?, i.e., que palavras disporei como centrais? τὰς δὲ καμήλους ἔταξε ἀντία τῆς ἵππου her. colocou os camelos frente aos cavalos 2 τάξας τὴν στρατιὴν ἅπασαν ἐξ ἐμβολῆς τοῦ ποταμοῦ her. tendo alinhado o exército lá de onde o rio irrompe, τάξαι νεῶν στῖφος μὲν στοίχοις τρισίν ésql. alinhar a esquadra de navios em três filas, τάττειν εἰς μάχην στρατιάν xen. posicionar o exército para a batalha 3 οὐδαμῶς γε τάττω ἐμαυτὸν εἰς τὴν τῶν ἄρχειν βουλομένων τάξιν xen. jamais me coloco na classe dos que desejam comandar, οὐδὲ εἰς τὴν δουλείαν ἐμαυτὸν τάττω xen. nem me coloco na categoria dos escravos 4 τάττομεν ἡμᾶς μὲν αὐτοὺς ἐπὶ τοὺς μένοντας xen. nós nos colocamos em face dos que resistem, Ξενοκ λέα μὲν καὶ ἄλλον ἔταξεν ἐπὶ τοὺς ἱππέας, Σκύθην δὲ ἐπὶ τοὺς νεοδαμώδεις ὁπλίτας xen. pôs Xênocles e um outro no comando dos cavaleiros e Cites no comando dos hoplitas recém-admitidos como cidadãos 5 ὁ ἀγαθὸς φίλος ἑαυτὸν τάττει πρὸς πᾶν τὸ ἐλλεῖπον τῷ φίλῳ xen. o bom amigo toma partido em relação ao que falta ao amigo 6 ἄρχοντας ἔταττον οὕστινας ἐκεῖνος κελεύοι xen. designavam como chefes aqueles que ele ordenava, ἑαυτοὺς ἐπὶ τὴν διακονίαν τάττουσιν ταύτην plat. eles se encarregam desse serviço, ἄνδρα ἐφ᾽ ἑκάστῳ τῶν τόπων ἔταξε τὸν ἐπιτήδειον παραδέχεσθαι τὰ φερόμενα γράμματα xen. em cada um desses lugares situou um homem incumbido de receber as cartas trazidas, ἡμᾶς δὲ πομποὺς καὶ κομιστῆρας κόρης τάσσουσιν εἶναι eur. [os aqueus] determinam que sejamos nós os acompanhantes e condutores da moça 7 πόλις γὰρ ἡμῖν ἃ με χρὴ τάσσειν ἐρεῖ; sóf. a cidade é que nos dirá as ordens que devo dar? φόρους ἔταξε ἑκάστοισι her. fixou tributos para cada [povo], μέτρ’ ἀνθρώποισι καὶ μέρη σταθμῶνἸσότης ἔταξε eur. Equidade fixou para os homens as medidas e as porções dos pesos, ἐγὼ γὰρ ὑπὲρ αὐτοῦ δίκην δίδωμί σοι ἣν ἂν σὺ τάξῃς ar. eu te pago no lugar dele a indenização que fixares, μισθὸν δὲ καὶ τούτοις Βαβυλωνίους ἔταξε παρέχειν xen. determinou que os babilônios pagassem o soldo a esses [guardas] 8 ἔταττον τὸ ὀρχεῖσθαι ἐπὶ τοῦ κινεῖσθαι at. empregavam a palavra “dançar” com o sentido da palavra “mover-se” 9 οἱ Πελοποννήσιοι εἴκοσι μὲν ναυσὶ πρὸς τοὺς Κερκυραίους ἐτάξαντο tuc. os peloponésios posicionaram-se com vinte navios contra os corcireus 10 ἔπλεον, ἐπὶ τεσσάρων ταξάμενοι τὰς ναῦς ἐπὶ τὴν ἑαυτῶν γῆν tuc. tendo disposto as naus em quatro fileiras, puseram-se a navegar em direção à terra deles 11 φόρον τε ἐτάξαντο καὶ δῶρα ἔπεμπον her. [os líbios] comprometeram-se com o pagamento de um tributo e puseram-se a enviar presentes, Κόλχοι δὲ τὰ ἐτάξαντο ἐς τὴν δωρεήν her. os colcos se comprometeram com o custeio da dádiva, χρήματα ἐτάξαντο ἀντὶ τῶν νεῶν τὸ ἱκνούμενον ἀνάλωμα φέρειν tuc. comprometia-se a pagar em dinheiro a contribuição devida em vez de fornecer navios, χρήματα τὰ ἀναλωθέντα ταξάμενοι κατὰ χρόνους ἀποδοῦναι tuc. tendo-se comprometido a pagar em dinheiro os gastos da guerra dentro de certos prazos 12 ἀποτίνει ζημίην τὴν ἂν οἱ ἱρέες τάξωνται her. [a pessoa que mata sem querer um animal consagrado] paga a multa que os sacerdotes fixarem, ἐτάξατο φόρους οἱ προσιέναι her. decidiu, de seu pleno poder, que um tributo lhe devia ser pago 13 ἀγγέλλεται τοῖσι ἄλλοισιἝλλησι τοῖσι τεταγμένοισι περὶ τὸἭραιον her. anuncia-se aos outros helenos, que estavam postados ao redor do templo de Hera, ἐπειρᾶτο προσβαίνων κατὰ τοῦτο τῆς ἀκροπόλιος τῇ οὐδεὶς ἐτέτακτο φύλακος her. fazia uma tentativa de escalada numa parte da cidadela em que não fora colocada nenhuma sentinela, ἐς τὸ οὖρος ταχθῆναι her. ter seu posto na montanha, ἐς πεζὸν τετάχθαι her. tem seu posto na infantaria, οἱ ἐς τὸν ναυτικὸν στρατὸν ταχθέντες her. os que foram designados para a frota, τῆς ὑστέρας τεταγμένος, ἐπίπροσθεν ἔχων ἄλλον, ἔτι θαρρεῖς plat. mesmo ocupando o último lugar e tendo outro à tua frente, ainda resistes 14 οἱ Κύρειοι πρόσθεν σὺν ἡμῖν ταττόμενοι νῦν ἀφεστήκασιν xen. os soldados de Ciro, que tentavam resistir à frente conosco, agora desertaram, οἱ μὲν σὺν τῷ Γωβρύᾳ καὶ Γαδάτᾳ τεταγμένοι xen. as tropas alinhadas sob o comando de Góbrias e de Gádatas, πρὸς τὴν τῶν Λακεδαιμονίων συμμαχίαν ταχθῆναι tuc. entrar para a aliança dos lacedemônios 15 ὥσπερ ἐτάχθη τὸ πρῶτον tuc. como havia sido decidido em primeiro lugar, οἱ ἐπὶ τούτῳ τεταγμένοι νόμοι plat. as leis prescritas sobre isso, τὰ δίκαια ταχθέντα εἶναι καὶ ἄδικα plat. o que está assentado como justo e injusto, τεταγμένα μὲν ποιεῖ, τεταγμένα δὲ λαμβάνει xen. ele faz e recebe o que é determinado, τὰ τεταγμένα ποιεῖν xen. cumprir as ordens, οἱ τριακόσιοι αὐτῶν, οἷς ἐτέτακτο παραβοηθεῖν εἴ τι δέοι tuc. trezentos deles, para os quais havia sido determinado que acorressem em socorro se houvesse necessidade, φόρος ταχθείς tuc. tributo imposto; τεταγμένος χρόνος her. tempo fixado; τὸ τεταγμένον xen. o lugar determinado, ἡ ταχθεῖσα ἕδρα ou τάξις xen. lugar ou posto determinado, τεταγμένη θυσία xen. sacrifício regular, τὰ τεταγμένα ὀνόματα isócr. as expressões usadas 16 ταχθεὶς ὑπὸ τοῦ ἐμοῦ ἀδελφοῦ οὗτος ἐπολέμησεν ἐμοὶ xen. tendo-se submetido às ordens de meu irmão, ele fez guerra contra mim 17 οἱ ἐπὶ τοῦτο ταχθέντες xen. os que haviam sido encarregados disso, οἱ Πέρσαι οἵ περ ἐτετάχατο ἐπ᾽ αὐτῷ τούτῳ her. os persas, justamente os que haviam sido incumbidos dessa missão, ὁ τοῖς γράμμασιν τεταγμένος pol. o incumbido das letras, i.e., o secretário, φωνεῖν ἐτάχθην ésql. recebi ordens para falar, τὸ ταχθέν sóf. a incumbência 18 οἵδε δὲ φόρον οὐδένα ἐτάχθησαν φέρειν her. a estes não foi imposto pagar um tributo 19 ἡγοῦνται κατὰ τάξιν ἣν ἕκαστος ἐτάχθη plat. [os deuses] exercem o comando de acordo com a classe em que cada um deles foi enquadrado.</p></section></article>\n<article id=\"entry-dgp-39664\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάττω</h1><div class=\"entry-meta\"><span>DGP · ordem 206 na letra τ · nº geral 39664</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = τάσσω.</p></section></article>\n<article id=\"entry-dgp-39665\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταΰγετον, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 207 na letra τ · nº geral 39665</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. Ταύγετα (τό) Taígeto, cadeia de montanhas entre a Lacônia e a Messênia.</p></section></article>\n<article id=\"entry-dgp-39666\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταΰγετος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 208 na letra τ · nº geral 39666</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Ταΰγετον.</p></section></article>\n<article id=\"entry-dgp-39667\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταύρειος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 209 na letra τ · nº geral 39667</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de touro; taurino 2 feito de couro de touro 3 do deus Touro, i.e., de Posidão. 〈ταῦρος〉</p></section></article>\n<article id=\"entry-dgp-39668\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταύρεος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 210 na letra τ · nº geral 39668</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ταύρειος. 〈ταῦρος〉</p></section></article>\n<article id=\"entry-dgp-39669\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταυρηδόν</h1><div class=\"entry-meta\"><span>DGP · ordem 211 na letra τ · nº geral 39669</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. à maneira de touro; feito um touro: τ. βλέπειν ou ὑποβλέπειν olhar como um touro, i.e, de esguelha e por baixo, atravessado. 〈ταῦρος, -δον〉</p></section></article>\n<article id=\"entry-dgp-39670\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταυρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 212 na letra τ · nº geral 39670</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da Táurida ♦ ἡ Ταυρική 2 Táurida ou Quersoneso Táurica.</p></section></article>\n<article id=\"entry-dgp-39671\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταυρόκερως, ω</h1><div class=\"entry-meta\"><span>DGP · ordem 213 na letra τ · nº geral 39671</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) tauricórnio, epít. de Dioniso.</p></section></article>\n<article id=\"entry-dgp-39672\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταυροκτονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 214 na letra τ · nº geral 39672</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">matar ou imolar um touro ou touros. 〈ταυροκτόνος〉</p></section></article>\n<article id=\"entry-dgp-39673\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταυροκτόνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 215 na letra τ · nº geral 39673</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">matador de touros. 〈ταῦρος, κτείνω〉</p></section></article>\n<article id=\"entry-dgp-39674\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταυροπόλα, ας</h1><div class=\"entry-meta\"><span>DGP · ordem 216 na letra τ · nº geral 39674</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) = ταυροπόλος.</p></section></article>\n<article id=\"entry-dgp-39675\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταυροπόλος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 217 na letra τ · nº geral 39675</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) honrada na Táurida, epít. de Ártemis. 〈ταῦρος, πολέω〉</p></section></article>\n<article id=\"entry-dgp-39676\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταυρόπους, ποδος</h1><div class=\"entry-meta\"><span>DGP · ordem 218 na letra τ · nº geral 39676</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) de pés de touro. 〈ταῦρος, πούς〉</p></section></article>\n<article id=\"entry-dgp-39677\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταῦρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 219 na letra τ · nº geral 39677</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 touro 2 sacerdote de Posidão Taurino 3 Medic. períneo ♦ Ταῦρος 4 Astron. Touro, constelação. [lat.]</p></section></article>\n<article id=\"entry-dgp-39678\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταυροσφάγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 220 na letra τ · nº geral 39678</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que mata touros 2 onde se imola touro. 〈ταῦρος, σφάττω〉</p></section></article>\n<article id=\"entry-dgp-39679\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταυρόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 221 na letra τ · nº geral 39679</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 transformar-se em touro; tornar-se touro 2 tornar-se furioso como um touro: ὄμμα ταυροῦσθαι eur. lançar olhar feroz. 〈ταῦρος〉</p></section></article>\n<article id=\"entry-dgp-39680\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταῦτα</h1><div class=\"entry-meta\"><span>DGP · ordem 222 na letra τ · nº geral 39680</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. n. de οὗτος.</p></section></article>\n<article id=\"entry-dgp-39681\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταὐτά</h1><div class=\"entry-meta\"><span>DGP · ordem 223 na letra τ · nº geral 39681</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τὰ αὐτά.</p></section></article>\n<article id=\"entry-dgp-39682\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταύτῃ</h1><div class=\"entry-meta\"><span>DGP · ordem 224 na letra τ · nº geral 39682</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. fem. sing. de οὗτος.</p></section></article>\n<article id=\"entry-dgp-39683\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταύτης</h1><div class=\"entry-meta\"><span>DGP · ordem 225 na letra τ · nº geral 39683</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. fem. de οὗτος.</p></section></article>\n<article id=\"entry-dgp-39684\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταυτί</h1><div class=\"entry-meta\"><span>DGP · ordem 226 na letra τ · nº geral 39684</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. por ταῦτα.</p></section></article>\n<article id=\"entry-dgp-39685\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταὐτό</h1><div class=\"entry-meta\"><span>DGP · ordem 227 na letra τ · nº geral 39685</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τὸ αὐτό.</p></section></article>\n<article id=\"entry-dgp-39686\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταὐτολογία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 228 na letra τ · nº geral 39686</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crist. repetição; tautologia. 〈ταὐτό, λέγω〉</p></section></article>\n<article id=\"entry-dgp-39687\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταὐτόματον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 229 na letra τ · nº geral 39687</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o que se produz espontaneamente: ἀπὸ ταὐτομάτου tuc. espontaneamente. 〈τὸ αὐτόματον〉</p></section></article>\n<article id=\"entry-dgp-39688\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταὐτόν</h1><div class=\"entry-meta\"><span>DGP · ordem 230 na letra τ · nº geral 39688</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = τὸ αὐτό.</p></section></article>\n<article id=\"entry-dgp-39689\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταὐτότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 231 na letra τ · nº geral 39689</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 identidade 2 repetição (de letra) 3 monotonia. 〈ταὐτό〉</p></section></article>\n<article id=\"entry-dgp-39690\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάφε</h1><div class=\"entry-meta\"><span>DGP · ordem 232 na letra τ · nº geral 39690</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor.2 poét. de τέθηπα.</p></section></article>\n<article id=\"entry-dgp-39691\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταφείς</h1><div class=\"entry-meta\"><span>DGP · ordem 233 na letra τ · nº geral 39691</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 pas. de θάπτω.</p></section></article>\n<article id=\"entry-dgp-39692\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταφεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 234 na letra τ · nº geral 39692</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que sepulta, que realiza os ritos funerários. 〈θάπτω〉</p></section></article>\n<article id=\"entry-dgp-39693\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταφή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 235 na letra τ · nº geral 39693</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sepultamento; funeral; exéquias 2 pl. sepulcro; sepultura; túmulo 3 gastos com sepultamento. 〈θάπτω〉</p></section></article>\n<article id=\"entry-dgp-39694\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταφήϊος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 236 na letra τ · nº geral 39694</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. sepulcral; fúnebre; funerário. 〈ταφή〉</p></section></article>\n<article id=\"entry-dgp-39695\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τάφιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 237 na letra τ · nº geral 39695</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Tafos; táfio.</p></section></article>\n<article id=\"entry-dgp-39696\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τἀφόδια</h1><div class=\"entry-meta\"><span>DGP · ordem 238 na letra τ · nº geral 39696</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de τὰ ἐφόδια.</p></section></article>\n<article id=\"entry-dgp-39697\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάφος1, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 239 na letra τ · nº geral 39697</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 funerais; ritos fúnebres; cerimônias (jogos ou banquetes) fúnebres: δαίνυ τάφον Ἀργείοισι hom. ofereceu um banquete funerário aos argivos, τελέσαι τάφον Ἕκτορι hom. realizar os ritos funerários em honra de Heitor, τάφου τυχεῖν eur. obter as honras da sepultura 2 túmulo; sepulcro. 〈θάπτω〉</p></section></article>\n<article id=\"entry-dgp-39698\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τάφος2, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 240 na letra τ · nº geral 39698</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tafo, ilha da costa da Arcanânia.</p></section></article>\n<article id=\"entry-dgp-39699\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάφος3, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 241 na letra τ · nº geral 39699</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estupor; surpresa. 〈τέθηπα〉</p></section></article>\n<article id=\"entry-dgp-39700\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταφρεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 242 na letra τ · nº geral 39700</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de cavar um fosso. 〈ταφρεύω〉</p></section></article>\n";
